import roman.core
import sys

# Helper to assert equality
def assert_eq(actual, expected, msg):
    if actual != expected:
        raise AssertionError(f'{msg}: got {actual!r}, expected {expected!r}')

# Test valid conversions
test_cases = [
    (1, 'I'),
    (4, 'IV'),
    (9, 'IX'),
    (40, 'XL'),
    (90, 'XC'),
    (400, 'CD'),
    (900, 'CM'),
    (2024, 'MMXXIV'),
    (3999, 'MMMCMXCIX'),
    (1994, 'MCMXCIV'),
]
for n, expected in test_cases:
    got = roman.core.to_roman(n)
    assert_eq(got, expected, f'to_roman({n})')
    # Also check that the result is considered a Roman numeral by is_roman_numeral
    if not roman.core.is_roman_numeral(got):
        raise AssertionError(f'to_roman({n}) produced invalid Roman numeral: {got!r}')

# Test int subclass
class MyInt(int):
    pass

for n, expected in test_cases[:3]:  # just a few
    got = roman.core.to_roman(MyInt(n))
    assert_eq(got, expected, f'to_roman(MyInt({n}))')

# Test out-of-range ints
for n in [0, -1, 4000]:
    try:
        roman.core.to_roman(n)
        raise AssertionError(f'to_roman({n}) did not raise ValueError')
    except ValueError:
        pass
    except Exception as e:
        raise AssertionError(f'to_roman({n}) raised wrong exception: {type(e).__name__}: {e}')

# Test out-of-range int subclass
class MyInt2(int):
    pass
for n in [0, 4000]:
    try:
        roman.core.to_roman(MyInt2(n))
        raise AssertionError(f'to_roman(MyInt2({n})) did not raise ValueError')
    except ValueError:
        pass
    except Exception as e:
        raise AssertionError(f'to_roman(MyInt2({n})) raised wrong exception: {type(e).__name__}: {e}')

# Test non-int inputs
non_ints = ['5', 5.0, None, [1], {'a':1}, set(), b'']
for x in non_ints:
    try:
        roman.core.to_roman(x)
        raise AssertionError(f'to_roman({x!r}) did not raise TypeError')
    except TypeError:
        pass
    except Exception as e:
        raise AssertionError(f'to_roman({x!r}) raised wrong exception: {type(e).__name__}: {e}')

# Test bool (optional) - we just call and see what happens; we don't assert.
# But we can note that if it raises TypeError, that's fine; if it returns something, also fine.
# We'll just call to avoid crashing.
try:
    roman.core.to_roman(True)
except Exception:
    pass
try:
    roman.core.to_roman(False)
except Exception:
    pass

print('All tests passed')
